 61	    private static final class ArticulationPointFinder {
 62	        private final Graph graph;
 63	        private final int[] discoveryTime;
 64	        private final int[] lowLink;
 65	        private final boolean[] visited;
 66	        private final boolean[] articulationPoint;
 67	        private int currentTime;
