 69	        private ArticulationPointFinder(Graph graph) {
 70	            int vertexCount = graph.vertexCount();
 71	            this.graph = graph;
 72	            this.discoveryTime = new int[vertexCount];
 73	            this.lowLink = new int[vertexCount];
 74	            this.visited = new boolean[vertexCount];
 75	            this.articulationPoint = new boolean[vertexCount];
 76	            this.currentTime = 0;
 77	        }
