 89	        private void visit(int vertex, int parent) {
 90	            visited[vertex] = true;
 91	            discoveryTime[vertex] = ++currentTime;
 92	            lowLink[vertex] = discoveryTime[vertex];
 93	
 94	            int childCount = 0;
 95	            for (int neighbor : graph.neighborsOf(vertex)) {
 96	                if (!visited[neighbor]) {
 97	                    childCount++;
 98	                    visit(neighbor, vertex);
 99	                    lowLink[vertex] = Math.min(lowLink[vertex], lowLink[neighbor]);
